    public async Task<IReadOnlyList<AttendanceRequestItem>> GetRequestsAsync(CancellationToken ct=default){await using var c=await Open(ct);await using var q=new NpgsqlCommand("""SELECT id,kind,employee_id,employee_name,employee_no,branch_name,work_date,requested_first_in_at,requested_last_out_at,requested_minutes,approved_minutes,multiplier,reason,status,requested_by,created_at FROM (SELECT a.id,'adjustment' kind,a.employee_id,concat_ws(' ',e.first_name,e.last_name) employee_name,e.employee_no,b.name branch_name,a.work_date,a.requested_first_in_at,a.requested_last_out_at,NULL::int requested_minutes,NULL::int approved_minutes,NULL::numeric multiplier,a.reason,a.status,u.display_name requested_by,a.created_at FROM attendance.adjustment_request a JOIN hr.employee e ON e.id=a.employee_id JOIN core.branch b ON b.id=a.branch_id JOIN auth.user_account u ON u.id=a.requested_by UNION ALL SELECT o.id,'overtime',o.employee_id,concat_ws(' ',e.first_name,e.last_name),e.employee_no,b.name,o.work_date,NULL,NULL,o.requested_minutes,o.approved_minutes,o.multiplier,o.reason,o.status,u.display_name,o.created_at FROM attendance.overtime_request o JOIN hr.employee e ON e.id=o.employee_id JOIN core.branch b ON b.id=o.branch_id JOIN auth.user_account u ON u.id=o.requested_by) x ORDER BY CASE status WHEN 'pending' THEN 0 ELSE 1 END,created_at DESC""",c);await using var r=await q.ExecuteReaderAsync(ct);var a=new List<AttendanceRequestItem>();while(await r.ReadAsync(ct))a.Add(new(r.GetGuid(0),r.GetString(1),r.GetGuid(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetFieldValue<DateOnly>(6),DTO(r,7),DTO(r,8),NI(r,9),NI(r,10),r.IsDBNull(11)?null:r.GetDecimal(11),T(r,12),r.GetString(13),r.GetString(14),r.GetFieldValue<DateTimeOffset>(15)));return a;}

    public async Task SaveCalendarAsync(HolidayCalendarForm m,Guid actor,CancellationToken ct=default){await using var c=await Open(ct);await using var q=new NpgsqlCommand(m.Id is null?"INSERT INTO attendance.holiday_calendar(branch_id,code,name,is_active,created_by,updated_by) VALUES(@branch,@code,@name,@active,@actor,@actor)":"UPDATE attendance.holiday_calendar SET branch_id=@branch,code=@code,name=@name,is_active=@active,updated_by=@actor WHERE id=@id",c);P(q,"branch",m.BranchId);q.Parameters.AddWithValue("code",m.Id is null?BusinessCode.New("CAL"):m.Code.Trim().ToUpperInvariant());q.Parameters.AddWithValue("name",m.Name.Trim());q.Parameters.AddWithValue("active",m.IsActive);q.Parameters.AddWithValue("actor",actor);if(m.Id is not null)q.Parameters.AddWithValue("id",m.Id.Value);await q.ExecuteNonQueryAsync(ct);}
